package com.adib.maintenance;
import android.content.*;import android.graphics.*;import android.net.Uri;import android.util.Base64;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.io.*;import java.util.Random;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class CommentCompressionTest {
 @Test public void noisyCommentPhotoIsBelow150KBAndKeepsAspectRatio()throws Exception{Context c=RuntimeEnvironment.getApplication();Bitmap b=Bitmap.createBitmap(1200,800,Bitmap.Config.ARGB_8888);int[] pixels=new int[1200*800];Random r=new Random(9);for(int i=0;i<pixels.length;i++)pixels[i]=0xff000000|r.nextInt(0x1000000);b.setPixels(pixels,0,1200,0,0,1200,800);File f=File.createTempFile("comment-noise",".png",c.getCacheDir());try{try(FileOutputStream out=new FileOutputStream(f)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();JSONObject image=NativeImageSupport.readPhoto(c,Uri.fromFile(f),150*1024);byte[] bytes=Base64.decode(image.getString("data"),Base64.NO_WRAP);assertTrue(bytes.length<=150*1024);assertEquals("image/jpeg",image.getString("mime"));BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);assertTrue(o.outWidth>0&&o.outHeight>0);assertEquals(1.5,o.outWidth/(double)o.outHeight,.01);}finally{f.delete();}}
 @Test public void tinyPNGIsNotReencodedOrInflated()throws Exception{Context c=RuntimeEnvironment.getApplication();Bitmap b=Bitmap.createBitmap(20,20,Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);File f=File.createTempFile("comment-small",".png",c.getCacheDir());try{try(FileOutputStream out=new FileOutputStream(f)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();byte[] original=java.nio.file.Files.readAllBytes(f.toPath());JSONObject image=NativeImageSupport.readPhoto(c,Uri.fromFile(f),150*1024);assertEquals("image/png",image.getString("mime"));assertArrayEquals(original,Base64.decode(image.getString("data"),Base64.NO_WRAP));}finally{f.delete();}}
}
